<?php declare(strict_types=1); namespace App\Models\Pmbm; use App\Enums\Pmbm\ApplicantStatus; use App\Models\{AcademicYear,Student,User}; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};
class PmbmApplicant extends Model { protected $guarded=[]; protected function casts():array{return ['status'=>ApplicantStatus::class,'birth_date'=>'date','submitted_at'=>'datetime','consent_at'=>'datetime','enrolled_at'=>'datetime','data'=>'array'];} public function academicYear():BelongsTo{return $this->belongsTo(AcademicYear::class);} public function student():BelongsTo{return $this->belongsTo(Student::class);} public function createdBy():BelongsTo{return $this->belongsTo(User::class,'created_by');} public function enrolledBy():BelongsTo{return $this->belongsTo(User::class,'enrolled_by');} public function documents():HasMany{return $this->hasMany(PmbmApplicantDocument::class,'applicant_id');} public function histories():HasMany{return $this->hasMany(PmbmStatusHistory::class,'applicant_id');} public function getGuardianNameAttribute():string{return $this->data['guardian_name']??$this->data['mother_name']??$this->data['father_name']??'—';} }
